   "discipline": "Level 3 Art History internals are judged by overall judgement at curriculum level 8: explanations that make explicit links between the standard's focus (media and processes, values, theory, texts or an argument) and specific, named art works or texts, deepening to analysis and then evaluation with integrated contextual evidence and conclusions. General background, biography and description of how works were made are not assessable evidence unless tied to the required explanations; length, essay style and research process are never the criterion.",
   "parallelHint": "different art works, artist, movement, theory, text or debate (e.g. a different modernist sculptor, a different art theory, a different art critic's text)",
