     "notes": [
      "EN2 — Examine involves using supporting evidence to explain the different values that are placed on art works.",
      "EN2 — Examine, in depth, involves using supporting evidence to analyse the different values that are placed on art works.",
      "EN2 — Examine, perceptively, involves integrating supporting evidence to produce an insightful analysis of the different values that are placed on art works.",
      "EN4 — Different values refer to the importance or lack of importance placed on art works. These may include: provenance, monetary, cultural, historical, political, religious, spiritual, symbolic, iconic, functional, aesthetic."
     ],
     "clarifications": {
      "date": "Updated August 2015",
      "points": [
       "Values are the relative worth or importance that individuals, societies and other groups assign to an art work, shaped by economic, cultural, national or other considerations.",
       "Teacher or student may select works; the selection must give scope to explain and analyse different values.",
       "Class/group work is allowed but the assessed response must be individual, written or recorded. Notes or annotated images are acceptable; bullet-pointed lists of single words are not.",
       "Supporting evidence is relevant information supporting the explanation and analysis of values; general information not linked to the discussion of values does not count.",
       "Achieved: explanations of different values supported by relevant evidence. Merit: analysis of the values using supporting evidence. Excellence: insight shown by integrating evidence into the analysis, leading to pertinent conclusions."
      ]
     },
     "nmr": [
      "Successful responses (2025) explicitly identified the different values placed on works by groups or individuals and explained the reasons with supporting evidence (e.g. artistic value in Duchamp's Fountain through the readymade raising questions about art).",
      "Evidence must be directly linked to the specific values discussed, not general commentary.",
      "Avoid lengthy background on artists or works unless it directly supports the analysis of values.",
      "When a value appears across several works, explain how it is shown in EACH work with specific evidence rather than one generalised explanation."
     ],
     "exemplars": [
      {
       "grade": "Achieved",
       "text": "Low Achieved (values placed on art in Nazi Germany): explains different values with supporting evidence. High Achieved (Russian Jack, a local public sculpture): clearly explains several values with well-referenced evidence and begins to analyse them.",
       "miss": "Not Merit because the analysis was not extensive enough — e.g. more evidence about popular and tourist values was needed."
      },
      {
       "grade": "Merit",
       "text": "Low Merit (Damien Hirst, For the Love of God): analyses the spiritual values placed on the work with evidence, though with superfluous discussion of meaning. High Merit (Nazi Germany): expansive analysis of the values Hitler's regime placed on art, with in-depth discussion of Die Brücke and Kirchner as evidence.",
       "miss": "Not Excellence because the significance of the different values was not expanded with integrated evidence to show insight."
      },
      {
       "grade": "Excellence",
       "text": "Low Excellence (different versions of Duchamp's Fountain): integrates evidence into an insightful analysis of the values placed on the versions. NZQA suggests sustaining the analysis and developing celebrity and consumer values raised in the final paragraph."
      }
     ],
