      "EN2 — Integrate biological knowledge to develop a comprehensive informed response (Excellence) involves: justifying the personal position and proposed action(s) by analysing and evaluating the biological knowledge related to the issue. This may include: comparing the significance of implications; considering the likely effectiveness of the proposed action(s); commenting on sources and information, considering ideas such as validity (currency, peer review status, scientific acceptance) and bias (attitudes, values, beliefs).",
      "EN3 — Integrate refers to selecting and collating relevant biological knowledge to develop an informed response.",
      "EN4 — A socio-scientific issue has both biological and social implications. The issue is one for which people hold different opinions or viewpoints. Social implications may be economic, ethical, cultural, or environmental.",
