     "notes": [
      "EN2 — Develop a marketing plan typically involves setting marketing aims, explaining the market situation, creating a marketing strategy and writing a marketing plan through: stating business knowledge relevant to the marketing plan; stating a Māori business concept(s) where relevant.",
      "EN2 — Develop an in-depth marketing plan typically involves fully explaining the market situation, creating a sound marketing strategy and writing a sound marketing plan through: including business knowledge relevant to the marketing plan; including a Māori business concept(s) where relevant.",
      "EN2 — Develop a comprehensive marketing plan typically involves evaluating the market situation, creating a thorough marketing strategy and writing a thorough marketing plan through: integrating business knowledge relevant to the marketing plan; integrating a Māori business concept(s) where relevant.",
      "EN3 — Marketing aims refer to mission statement and corporate objectives.",
      "EN4 — The market situation refers to marketing audit, SWOT analysis, marketing assumptions.",
      "EN5 — Marketing strategy refers to marketing objectives, SMART goals, forecasting, contingency plans.",
      "EN6 — Marketing plan refers to marketing budget and detailed action plan for implementation and future monitoring."
     ],
     "clarifications": {
      "date": "September 2015",
      "points": [
       "Marketing objectives align with business objectives: for a new product students create SMART objectives; for an existing product they research the supplier’s business and marketing objectives or derive marketing objectives from the business objectives.",
       "Marketing audit: for a new product, audit the existing marketing of the closest competing product in the market it will enter; for an existing product, use secondary research into existing marketing aims and activities.",
       "Required for both: market research to address issues from the audit; a marketing strategy linked to the marketing objectives; a contingency plan; a comprehensive action plan for implementation and future monitoring (timeline or Gantt chart).",
       "Sales forecasts and budget should be realistic ‘best guess’ figures, researched as far as feasible and covering all aspects of the strategy; assumptions will be needed.",
       "The contingency plan should go beyond simply cutting prices or increasing advertising and address threats identified in the audit.",
       "At all grades, relevant level 8 business knowledge is applied throughout the audit and plan.",
       "Achieved: explain how and/or why the marketing situation exists and build a strategy consistent with the marketing objectives and mission/corporate objectives. Merit: richer explanations of each part. Excellence: aspects of the plan linked together, evidence used to justify chosen strategies, and each strategy’s impact on the business evaluated."
      ]
     },
     "nmr": [
      "Achieved: a marketing aim for launching a new product or growing an existing product’s market share in New Zealand, with market research from a marketing audit shaping the strategy; strategies and their costs specified; an action plan staged to match the sales forecast and budget; monitoring and contingency plans if forecasts are not met.",
      "Budget estimates should be backed by research or data — ‘free’ platforms still carry costs in time, content quality and possibly paid promotion.",
      "At all grades students need level 8 tools (e.g. PEST/PESTLE, Boston Matrix, Ansoff Matrix, Porter’s Five Forces, STP). SWOT or the 4 Ps may help but are not enough on their own. Tools should fit the objectives and be applied, not described.",
      "A significant number of moderation grade changes occurred at the Merit/Excellence boundary in 2025 and previous years.",
      "Excellence: plan elements link together and evidence justifies strategies — e.g. a Boston Matrix ‘problem child’ reflected in a high marketing budget, with a contingency if it does not become a star. Comprehensive plans recognise uncertain markets, with a detailed timeline and contingencies covering plausible risks and alternative strategies.",
      "Where a Level 3 marketing plan relates to the 91384 business activity, separate evidence must be submitted for 91382, which requires much more marketing detail."
     ],
