       "Agency websites are a starting point; consultation can be face-to-face, video call or email and should be supported by evidence. A teacher may facilitate consultation because of agency workloads, but students decide what information is gathered.",
       "Domestic consultation examples: customs agents, ExportNZ, Asia New Zealand Foundation, NZTE, MFAT, NZ Chamber of Commerce. International: a relevant overseas business, customs agent, trade commission, embassy or agency in the target country.",
       "Business knowledge: the export process (cultural intelligence, transport, distribution, finance, intellectual property, compliance, trade agreements, exchange rates), advisory agencies, export readiness, risks and opportunities of global expansion, Māori business concepts where appropriate. Vocabulary used correctly and in context.",
