      "date": "September 2015 (updated in its entirety)",
      "points": [
       "Clarifications do not introduce new criteria or change the requirements of the standard; examples are illustrations only.",
       "The problem must give students sufficient scope to demonstrate and develop their own thinking. If the problem has parts, all of the parts need to contribute to the solution.",
       "A task with a number of discrete skills-based questions is not appropriate for demonstrating the required levels of thinking.",
       "Students need to make their own decisions about what to do and how to solve problems. A task that gives a series of steps leading to the solution is likely to reduce the opportunity to demonstrate all levels of thinking.",
       "Expected evidence for Achieved includes selecting and using methods; to be used as evidence a method must be relevant to the solution of the problem.",
       "An instruction such as \"Sketch the conic y² = 4(x−2)\" is inappropriate because it tells students what to do.",
       "The methods need to be at curriculum level 8. Parabolas need to be related to the form y² = 4ax.",
       "EN4: properties of conic sections are attributes common to all conics in a group — e.g. hyperbolae have two branches and two asymptotes.",
       "For example, students need to identify the properties of the conic section they have used to form the equation.",
       "Communicating solutions is required at all grades: Achieved — indicate what the answer represents; Merit — clearly indicate what is being found and link solutions to the context; Excellence — explain any decisions made in solving the problem."
      ]
