     "credits": 4,
     "version": "Version 2 (published 17 November 2016)",
     "verified": "2026-10-25",
     "title": "Carry out an investigation in chemistry involving quantitative analysis",
     "criteria": {
      "achieved": "Carry out an investigation in chemistry involving quantitative analysis.",
      "merit": "Carry out an in-depth investigation in chemistry involving quantitative analysis.",
      "excellence": "Carry out a comprehensive investigation in chemistry involving quantitative analysis."
     },
     "notes": [
      "EN2 — Carry out an investigation (Achieved) involves: exploring a possible trend or pattern in the quantity of substance in a sample; developing and carrying out a procedure to collect data about a possible trend or pattern in the quantity of a substance; collecting and recording a sufficient quantity of data to enable a conclusion to be reached; processing of the data to reach a conclusion; presenting a report that contains a statement of the purpose of the investigation, a description of the procedure that includes preparation of samples and the analytical technique used, a summary of the collected and processed data, and a conclusion based on the processed data.",
      "EN2 — Carry out an in-depth investigation (Merit) involves: collection of quality data which includes standardising the standard solution(s) and control of significant variables; accurate processing of the data to reach a valid conclusion; providing evidence of the mathematical steps used to process the experimental data; presenting a report that contains a description of the procedure in sufficient detail for the investigation to be duplicated, a conclusion that links the processed data to the purpose of the investigation, and an explanation of how the procedure used contributed to the collection of quality data.",
      "EN2 — Carry out a comprehensive investigation (Excellence) involves: accurate processing of the data using appropriate significant figures and units; presenting a report that shows evidence of justifying the steps used in the procedure in relation to the reaction(s) occurring and to the nature of the samples being analysed, and a comprehensive evaluation of the investigation that includes a selection from: evaluation of the reliability of the data by considering the procedure used and possible sources of error; justification of how the processed data supports the conclusion(s); linking the conclusion(s) to chemical principles and/or real life applications.",
      "EN3 — A logbook needs to be kept throughout the investigation. The logbook contains details of the development of the purpose, procedure, raw data, and calculations.",
      "EN4 — Instructions may be provided for an analytical technique that may be used in a school laboratory, or equivalent.",
      "EN5 — The investigation is based on an analytical technique such as titration (acid-base or redox) or colorimetry.",
      "EN6 — To enable a conclusion to be reached titre data values of at least 5 mL are required or for colorimetry the range of the standard curve must be appropriate."
     ],
     "clarifications": {
      "date": "March 2016 (updated in its entirety)",
      "points": [
       "Titration may be acid-base or redox. An acid-base titration must be a non 1:1 reaction unless it is a back titration.",
       "A trend usually involves continuous data (e.g. chloride concentration at increasing distance from the sea; vitamin C in juice over storage time). A pattern usually involves discontinuous data (e.g. calcium in milk from cows on different pastures; phosphate in urban versus rural waterways).",
       "Consumer testing or quality control is NOT acceptable at this level (e.g. comparing a juice's vitamin C with the manufacturer's stated value).",
       "Students may work in groups, but assessors must ensure each student has met the standard.",
       "The report need not include standard solution preparation or raw data, but these should be in the logbook.",
       "Grades are based on the quality of the investigation; Excellence also requires evidence of understanding the chemistry principles involved.",
       "Merit: significant variables controlled, including standardising a solution or the student making a standard solution; accurate processing with mathematical steps shown; detailed method, conclusion linked to purpose, explanation of how the procedure produced quality data.",
       "Excellence: appropriate significant figures and units; procedure steps justified in relation to the reactions and the nature of the samples; a comprehensive evaluation that links the conclusion to chemical principles and/or real-life applications AND either evaluates data reliability or justifies how the processed data supports the conclusion."
      ]
     },
     "nmr": [
      "Investigations that collected data allowing a pattern or trend to be investigated, with a report of the investigation and results, met the standard.",
      "Achieved needs strengthening: the procedure must describe sample preparation. Strong responses listed the steps for making the samples and the conditions the samples were stored in or exposed to.",
      "Excellence needs strengthening: steps must be justified. Strong responses explained why particular reactants were added, linking them to the relevant reactions so the dependent variable could be calculated."
     ],
