     "criteria": {
      "achieved": "Demonstrate understanding of chemical processes in the world around us.",
      "merit": "Demonstrate in-depth understanding of chemical processes in the world around us.",
      "excellence": "Demonstrate comprehensive understanding of chemical processes in the world around us."
     },
     "notes": [
      "EN2 — Demonstrate understanding (Achieved) involves processing and interpreting given information to identify, describe, and give an account of chemical processes occurring in the natural world or developed in response to an issue or need. The account given must be supported by the use of chemistry vocabulary, symbols, conventions, and equations.",
      "EN2 — Demonstrate in-depth understanding (Merit) involves making and explaining links between chemical processes, and the consequences of the chemical processes for the environment or people. This requires explanations that integrate chemistry vocabulary, symbols, conventions, and equations.",
      "EN2 — Demonstrate comprehensive understanding (Excellence) involves an evaluation of the impact of, and issues that have arisen from, the chemical processes. This involves elaborating on, comparing and contrasting, or analysing the links between the chemical processes and their consequences. This requires the consistent integration of chemistry vocabulary, symbols, conventions, and equations.",
      "EN3 — Chemical processes in the world around us include either the chemistry related to an environmental issue or the chemistry involved in the development of new technology to meet a societal need. Examples of environmental issues may include an aspect of the greenhouse effect, ozone depletion, acidification of oceans, acid rain, volcanic eruptions, or pollution. Examples of technologies may include an aspect of polymers, energy production, pharmaceuticals, or food production."
     ],
     "clarifications": {
      "date": "March 2016 (updated in its entirety)",
      "points": [
       "Students should be given sufficient resource material to process and interpret the information they need for their report, and may also use their own additional material.",
       "All grades: describe the chemical processes involved using appropriate chemical terminology, including chemical equations for the reactions occurring.",
       "Merit: explain the links between the chemical processes and their consequences for the environment and/or people, with coherent use of chemistry vocabulary, symbols, conventions and equations.",
       "Excellence: elaborate on the consequences for the environment and/or people; compare and contrast the processes used to meet needs, resolve issues or develop new technologies; consistently integrate chemistry vocabulary, symbols, conventions and equations."
      ]
     },
