     "title": "Apply spatial analysis, with consultation, to solve a geographic problem",
     "criteria": {
      "achieved": "Apply spatial analysis, with consultation, to solve a geographic problem.",
      "merit": "Effectively apply spatial analysis, with consultation, to solve a geographic problem.",
      "excellence": "Comprehensively apply spatial analysis, with consultation, to solve a geographic problem."
     },
     "notes": [
      "EN2 — Apply (Achieved) involves: collecting and presenting spatial data relevant to the geographic problem; completing manipulations of the spatial data to produce a layout related to the problem; explaining the manipulations; proposing a solution to the geographic problem.",
      "EN2 — Effectively (Merit) involves: collecting sufficient spatial data to address the geographic problem; completing manipulations of the spatial data to produce an accurate layout related to the problem; explaining the manipulations in detail; justifying the solution to the geographic problem. The justification demonstrates why the chosen course of action is better than the alternatives.",
      "EN2 — Comprehensively (Excellence) involves: evaluating the manipulations; fully justifying the solution to the geographic problem. The full justification is an in-depth response that uses clarity of argument and holistic understanding to demonstrate why one course of action is better than the alternatives.",
      "EN3 — With consultation means students initiate discussion with their teacher about which geospatial technique to use.",
      "EN4 — A geographic problem involves the natural and/or cultural environment and has a spatial dimension; it may be hypothetical but must use real spatial data.",
      "EN5–7 — Collecting spatial data means gathering data with a spatial component in the field or accessing it from other sources. A layout is a map, which may also include tables, graphs and images. Manipulations are data transformations, including measuring, layering, changing symbols, sorting and editing tables, querying maps, using coordinate systems, and displaying graphs based on maps.",
      "EN8 — Appropriate geospatial technology must be used to manipulate and present the data."
     ],
     "clarifications": {
      "date": "September 2015 (updated to address issues from moderation)",
      "points": [
       "Consultation helps students choose geospatial techniques suited to the problem; the teacher should guide the selection of a topic or theme.",
       "Sufficient, quality spatial data is needed. Manipulations should create new data using a range of transformation techniques.",
       "Spatial data should be presented as a layout, not as separate graphics integrated into the report. Geographic conventions and a range of skills must be evident in the completed layout.",
       "Merit is distinguished from Achieved by technical accuracy of the images (conventions), the range and selection of images, and a logical display showing sound understanding of the problem’s components and spatial dimension.",
       "Explanation of manipulations shows why particular techniques were used with specific data and how each manipulation supports problem solving, clearly linked to the layout. A comprehensive response evaluates the manipulations.",
       "The justification should show why the chosen course is better than the alternatives (focus on the proposal or the alternatives depending on the problem); in all cases the solution must be based on the spatial analysis and manipulations carried out."
      ]
     },
