      "EN2 — Analyse, perceptively (Excellence) involves recommending strategies based on a coherent explanation that connects the New Zealand health issue and the influence of the major factors on the issue to relevant underlying health concepts (hauora, socioecological perspective, health promotion, and attitudes and values). The perceptive analysis is supported by the coherent and consistent use of evidence.",
      "EN3 — A New Zealand health issue affects the well-being of an identified community or sector and is a matter of public concern (e.g. mental health and resilience, gender concepts, media portrayal of sexuality, teenage sexual health, drug use among 15-24 year olds, disease prevalence in specific populations, discrimination or harassment, ethnic or cultural issues, gambling, domestic violence). Focusing on suicide or eating disorders is not appropriate.",
      "EN4 — Supported by evidence refers to the use of specific and relevant details to support an analysis. Evidence may include examples, quotations and/or data from credible and current sources such as government ministry websites, recognised NGOs, research journals and other publications. Generally, current research means data or theories published within the last five years."
