   "slug": "media-studies",
   "discipline": "Level 3 Media Studies internals are judged on analysis and evaluation at curriculum level 8: explaining how and why meaning, representation or change is produced, then analysing its impact and evaluating its significance for the text, the media and/or society, supported by integrated evidence from texts, research and viewpoints. Description, chronology or a general discussion of a theory or issue with a few examples does not meet the standard; length is never the criterion.",
   "parallelHint": "a different film or media text, a different aspect of New Zealand culture or society, or a different media development (e.g. another ownership, technology, delivery or regulatory change)",
   "privacyNote": "",
