   "slug": "physical-education",
   "discipline": "Level 3 Physical Education internals are judged on the quality of the student’s thinking about movement: biophysical and socio-cultural knowledge applied to a specific skill, programme, context or the student’s own experiences, with judgements or conclusions justified by specific examples from that experience or from research. Merit rests on detailed examination and coherent (clear, connected) judgements; Excellence almost always needs assumptions to be identified, questioned and challenged, with insightful judgements built on that challenge. Length, the number of principles listed, referencing and the student’s own physical ability are never criteria in themselves.",
   "parallelHint": "a different physical activity, skill, programme goal, outdoor activity, event or target group (e.g. a netball shot instead of a golf drive, kayaking instead of skiing, a different sporting event or leadership context)",
   "privacyNote": "Personal reflections and programme logs (especially 91498, 91500, 91503 and 91789) often contain health, injury, body-image, disability, family and socio-economic information. Remove names and identifying details before pasting, and handle any disclosure through the school’s pastoral processes rather than in feedback.",
