      "EN2 — Devise in-depth strategies (Merit) involves selecting and explaining, using coherent reasoning, the knowledge that underpins the strategies to achieve the physical activity outcome.",
      "EN2 — Devise comprehensive strategies (Excellence) involves selecting and explaining, using coherent and insightful reasoning by questioning and challenging assumptions, the knowledge that underpins the strategies to achieve the physical activity outcome.",
      "EN3 — Devise strategies is the process by which knowledge is applied to meet the intended purpose of the physical activity outcome for self or others. This involves developing the strategies, trialling them and adjusting them as a result of a process of ongoing reflection.",
      "EN4 — Knowledge relates to: biophysical (may include anatomy, biomechanics, physiology, psychology, skill acquisition, methods/principles of training); socio-cultural (may include societal, political, economic, environmental, ethical, cultural, historical factors); the specific physical activity context.",
      "EN5 — A physical activity outcome is the goal, purpose, or end point of the activity, such as developing fitness or improving game play.",
      "EN6 — A physical activity outcome may relate to working with individuals or groups in: outdoor education experiences, recreation activities, festival/cultural activities, coaching experiences, physical performance improvement."
