       "Focus on the strategies most relevant to the outcome; the strategies explained should be the ones trialled.",
       "Responses must include: a clear statement of the intended outcome; clear identification of each strategy; how and why each strategy will be applied to meet the outcome; specific examples of how each would be applied.",
