      "EN2 — Carry out an in-depth practical investigation (Merit) involves: describing the control of other variable(s) that could significantly affect the results; using techniques to improve the accuracy of measurements; determining uncertainties in one of the variables expressed in the graphical analysis; graphical analysis which expresses the uncertainty in the relationship consistent with the uncertainty in the data; providing a conclusion that makes a quantitative comparison between the physics theory and the relationship/quantity obtained from the experimental data which includes consideration of uncertainties.",
      "EN2 — Carry out a comprehensive practical investigation (Excellence) involves a discussion which addresses issues critical to the practical investigation, such as: the other variable(s) that could have changed and significantly affected the results, and how they could have changed the results; the limitations to the theory's applicability both in the practical situation and/or at extreme values of the independent variable; any unexpected outcomes of the processing of the results and a suggestion of how they could have been caused and the effect they had on the validity of the conclusion.",
      "EN3 — A practical investigation is an activity that includes gathering, processing and interpreting data.",
      "EN4 — The variables under investigation should have a non-linear relationship according to a physics theory provided in the task."
