      "date": "December 2017 (updated in its entirety from moderation issues)",
      "points": [
       "The investigation compares the relationship, or a quantity determined from the graph, with the physics theory. Assessment may be a single event or a portfolio; each experiment is a complete investigation. At least FIVE values of the independent variable are required.",
       "The theory to be tested and relevant background should be provided, but NOT a template.",
       "Data may be gathered in pairs, but each learner must be involved in measuring. Group discussion or teacher input is not appropriate once data has been gathered. Assessors must be able to verify authenticity.",
       "The conclusion states the equation or value from the graph and compares it with theory, e.g. type of relationship versus expected, derived quantity versus theoretical value, experimental versus theoretical gradient, or experimental versus expected intercept. Uncertainty may be shown as an error line on a linear graph.",
       "Merit: a control variable must significantly affect the results (describing irrelevant controls is not evidence); uncertainty evidence may include error bars on transformed or untransformed variables; the comparison is quantitative with an equation including uncertainties from the graph.",
       "Excellence: issues may go beyond those in the EN; discussing a critical issue must explain why it affects the investigation and how it affects the measured variable or the gradient used in the comparison; overall, the equivalent of two good discussion points."
      ]
