   "discipline": "Level 3 Psychology is judged on analysis: discussing how approaches, research and theories work and interact, then critiquing them with descriptions of or references to published theories, concepts and studies (Merit), and finally producing a detailed critique that weighs degree, effectiveness or validity and traces the impact on wider society (Excellence). Description of a study or theory, however accurate or long, never meets the standard by itself; claims must be backed by explanation, evidence or examples, and research must comply with the NZ Code of Ethics.",
