     "title": "Analyse the interaction between psychological approaches",
     "criteria": {
      "achieved": "Analyse the interaction between psychological approaches.",
      "merit": "Analyse, in depth, the interaction between psychological approaches.",
      "excellence": "Comprehensively analyse the interaction between psychological approaches."
     },
     "notes": [
      "EN2 — Analyse (Achieved) involves discussing at least two psychological approaches focusing on the methodological and theoretical differences between each approach and how they interact.",
      "EN2 — Analyse, in depth (Merit) involves critiquing how the approaches interact with each other. The critique includes descriptions of, or references to, psychological theories, concepts and/or studies from published works.",
      "EN2 — Comprehensively analyse (Excellence) involves a detailed critique focusing on the degree of interaction between the approaches and showing the impact of these interactions in a societal context.",
      "EN3 — Psychological approaches refer to paradigms about people and the way that they function. There may be several different theories within an approach, but they share common assumptions that tie them to that approach. Different approaches may offer different explanations for behaviours. Examples include: behavioural, biological, cognitive, sociocultural, evolutionary, humanistic, psychodynamic."
     ],
     "clarifications": {
      "date": "undated (NZQA Level 3 information page, sighted October 2026)",
      "points": [
       "Approaches are assumptions or perspectives about human nature; they are the starting points for, or are illustrated by, theories and studies.",
       "The focus should be on how the approaches interact, and on the extent to which specific theories or studies show that interaction."
      ]
     },
     "nmr": [],
     "exemplars": [
      {
       "grade": "Achieved",
       "text": "Biological and sociocultural explanations of aggression: methodological and theoretical differences compared, with a basic account of interaction — an MAOA gene predisposition (neurotransmitters, emotional regulation) raises vulnerability and a violent social environment reinforces the behaviour.",
       "miss": "Not Merit because the interaction needed to be explained more explicitly: the sociocultural environment described in more detail (e.g. whether twins were raised together, family microenvironments), the specific environments that interact with the MAOA gene identified, and these linked clearly to sociocultural theory or research."
      },
      {
       "grade": "Merit",
       "text": "Critiques the interaction using published theories — the General Aggression Model (Anderson) and the Catalyst Model (Ferguson) — recognising that the GAM was built to overcome single-factor explanations, explaining how environmental strain acts on an existing biological predisposition, weighing the relative contributions, and identifying ethical concerns such as MAOA screening.",
       "miss": "Not Excellence because it needed to critique the evidence and theory with explicit reference to the behavioural approach and/or evaluate the strengths of an interactionist explanation, connect the ethical issues to socially sensitive research, and explicitly discuss the effects on society."
      },
      {
       "grade": "Excellence",
       "text": "Argues that interaction between the approaches is limited because they rest on contrasting objective and subjective perspectives; uses Meehl's diathesis-stress model to show how genetic vulnerability and environmental stressors interact in schizophrenia; concludes the approaches work together in practice but stay conceptually distinct; extends to society through treatment and relapse reduction (Falloon; Pederson) where combining biological and psychodynamic/family therapy improves recovery. NZQA notes the detailed critique of the DEGREE of interaction and clear evaluation of societal impact."
      }
     ],
     "conditions": [
      "Teachers may provide reference material on the approaches, including published theories and studies (NZQA Remote Assessment Matrix).",
      "Check points and verbal conferencing during the assessment period are recommended for authenticity (NZQA Remote Assessment Matrix)."
     ],
     "components": [
      "Methodological and theoretical differences between the approaches",
      "How the approaches interact",
      "Critique using published theories and studies",
      "Degree of interaction and impact in a societal context"
     ],
